"""Render the phase evidence without touching the frozen model."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'results/v0.12/rms'
def read(name):return json.loads((OUT/name).read_text())
rows=read('rows.json');val=[r for r in rows if r['role']=='validation']; stats=read('summary.json')['rmsnorm'];cost=read('costs.json')['rmsnorm'];ev={tuple(r['shape']):r for r in read('holdout-evidence.json')};lines=['# 950DT RMSNorm 误差诊断','', '| 范围 | n | v0.11 WAPE / max | v0.12 WAPE / max | 固定 WAPE | 给定 H 的 v0.12 WAPE |','|---|---:|---:|---:|---:|---:|']
for role,group,label in [('development','all','开发回放'),('validation','all','全新冻结验证'),('validation','few_wide','新：T≤4、D≥2048'),('validation','controls','新：普通'),('validation','large','新：主输出 ≥1 MiB（与普通重叠）')]:
    s=stats[role][group];p=s['predicted_us'];q=s['previous_us'];lines.append(f"|{label}|{p['n']}|{100*q['wape']:.2f}% / {100*q['max_ape']:.2f}%|{100*p['wape']:.2f}% / {100*p['max_ape']:.2f}%|{100*s['fixed_us']['wape']:.2f}%|{100*s['sequence_us']['wape']:.2f}%|")
lines+=['','WAPE=∑|预测−CA|/∑CA；max 为单点绝对相对误差最大值。固定对照使用 43 个旧 shape 的中位数。H 为同一 CA 进程此前活跃 AIV 的最高值，默认预测未使用它。','', '| 新 shape | H/AIV | 最忙核块行 | CA / v0.11 / v0.12 (µs) | v0.12有符号误差 | 写并集 CA/预测 (tick) | 与SIMD重叠 CA/预测 (tick) | MTE3暴露 CA/预测 (µs) |','|---|---:|---|---:|---:|---:|---:|---:|']
for r in val:
    t,d=r['shape'];x=ev[t,d];p=r['prediction'];pred=p['stages_us'];ca=r['phase_us'];err=r['predicted_us']/r['reference_us']-1;ts='+'.join(map(str,p['ub_tile_rows']));lines.append(f"|[{t},{d}]|{r['prior_aiv']}/{r['active_aiv']}|{ts}|{r['reference_us']:.3f} / {r['previous_us']:.3f} / {r['predicted_us']:.3f}|{err:+.1%}|{x['write_ticks']} / {p['write_union_ticks']:.0f}|{x['overlap_ticks']} / {p['write_simd_overlap_ticks']:.0f}|{ca['MTE3']:.3f} / {pred['MTE3']:.3f}|")
worst=max(val,key=lambda r: abs(r['predicted_us']/r['reference_us']-1)); x=worst;parts=sorted(((abs(v-x['phase_us'].get(k,0)),k,v-x['phase_us'].get(k,0)) for k,v in x['prediction']['stages_us'].items()),reverse=True);delta='、'.join(f'{k} {v:+.3f} µs' for _,k,v in parts[:3]); lines+=['',f"误差最大的 {x['shape']}：默认阶段误差（预测−实测）主要为 {delta}。给定 H={x['prior_aiv']} 的预测为 {x['sequence_us']:.3f} µs。大小组分开的结果比单看 WAPE 更能说明适用边界。",'','**大 shape 是否线性。** 同为 D=4096 的 448 和 480 行会跨过 7→7+1 的 UB 边界；D=6144 的 384 和 512 行分别为 4+2、4+4。只在固定实现、相同核和启动状态下，向量工作和主输出字节才随每核行数近似线性；分核、尾块、相邻 rstd 写回和跨块覆盖都会改变总延迟。6144 两点的 H 和首次/热态不同，不能用它们拟合稳态斜率。', '', '**时序残差。** 统计量写回时长用一个有效邻接窗口概括，不能区分不同块的实际排队；建模时还把首次 rstd 至最后主输出发起之间的计算近似成一段连续掩盖窗口。多块时这两项会产生相反方向的误差，应结合上表的并集、交集和独占阶段检查。SIMD、MTE3 和剩余阶段对总时延可能互相抵消。首次或扩核的启动类别并非仅由 shape 决定；默认值为先验期望，不是单次调度状态的测量。','',f"**核验及成本。** 实际接口 `aclnnRmsNorm`，CANN 9.2.1 / `_9582`，10 个新 shape 都是 `entry_kernel_1388`、0 AIC，逐核两输出主/辅地址区间、实际字节、块行数均验证。两组全量 golden `bad=0`、helper flush、逐核 RV、核数、跨核 makespan 与分段闭合通过。不把 helper 的 overwrite/end-only 计数当作金标 ISA 条数。初批 10 个目标只有 6 个合格，2 个空库和 2 个输出超量隔离；只对这 4 个目标重试，并用 3 个控制启动维持原来的 H，共 {cost['launches']} 次启动。所有库（含失败与预热）占 {cost['db_bytes']/2**30:.3f} GiB，总采集 {cost['batch_wall_s']:.1f} 进程秒；两波并发有效运行约 {cost['two_wave_ca_wall_s']:.1f}s（不含轮次间脚本准备）。加载 profile 后，10 个 shape 各 100 次无 shape 缓存直调，中位 {cost['query_median_us']:.2f} µs、观察最大 {cost['query_max_us']:.2f} µs。此处不是设备上板计时，首次 Python 解释器启动也不计入查询。",'','交付索引：`freeze.json`（冻结时间、哈希和预算）、`development-evidence.json`（43 个旧库，逐核事件）、`original-attempts.json`/`recovery-contract.json`（无效首批及恢复）、`holdout-audit.json`/`holdout-evidence.json`（合格小样本）、`rows.json`/`summary.json`/`costs.json`。']
(OUT/'diagnosis.md').write_text('\n'.join(lines)+'\n')
